import { HTMLAttributes } from 'react';
import { CommonProps } from '../../utility/commonProps';
import { AvatarProps } from '../Avatar/Avatar.types';
/**
 * User data for avatar group display
 * Extends the existing Avatar component interface with additional user information
 *
 * Note: userName is required (not optional like in AvatarProps) because AvatarGroup
 * relies on it for accessibility labels, tooltips, and screen reader support.
 *
 * @example
 * ```tsx
 * const user: AvatarGroupUser = {
 *   id: "user-123",
 *   userName: "John Doe",
 *   src: "/profile.jpg",
 *   color: "blue",
 *   info: {
 *     role: "Senior Developer",
 *     company: "Walmart Data Ventures",
 *     email: "john.doe@walmart.com"
 *   }
 * };
 * ```
 */
export interface AvatarGroupUser extends Pick<AvatarProps, 'src' | 'color' | 'info' | 'type'> {
    /**
     * Unique identifier for the user
     * Used for React keys and accessibility labeling
     * @example "user-123", "john-doe", "jdoe@walmart.com"
     */
    id: string;
    /**
     * User's display name - REQUIRED for AvatarGroup
     *
     * Used for:
     * - Generating avatar initials
     * - Accessibility labels and ARIA attributes
     * - Tooltip displays showing visible user names
     * - Screen reader announcements
     *
     * Unlike the optional userName in AvatarProps, this is required
     * because AvatarGroup functionality depends on it for proper
     * accessibility and user experience.
     *
     * @example "John Doe", "Jane Smith", "Bob Johnson"
     */
    userName: string;
}
/**
 * Avatar Group component props interface
 *
 * The AvatarGroup component displays a collection of user avatars in an overlapping layout.
 * It automatically handles overflow by showing a "More" indicator when exceeding the maximum count.
 *
 * @example Basic usage
 * ```tsx
 * <AvatarGroup
 *   users={[
 *     { id: "1", userName: "John Doe" },
 *     { id: "2", userName: "Jane Smith" },
 *     { id: "3", userName: "Bob Johnson" }
 *   ]}
 *   size="medium"
 * />
 * ```
 *
 * @example With overflow handling
 * ```tsx
 * <AvatarGroup
 *   users={allUsers}
 *   maxVisible={4}
 *   moreIndicatorTooltip="View all collaborators"
 *   onMoreIndicatorClick={(hiddenUsers, totalCount) => {
 *     openModal({ users: hiddenUsers, total: totalCount });
 *   }}
 * />
 * ```
 *
 * @example Different sizes
 * ```tsx
 * // Compact for lists
 * <AvatarGroup users={users} size="xsmall" />
 *
 * // Standard for cards
 * <AvatarGroup users={users} size="medium" />
 * ```
 */
export interface AvatarGroupProps extends CommonProps, Omit<HTMLAttributes<HTMLDivElement>, 'size'> {
    /**
     * Array of users to display in the avatar group
     * Each user should have at minimum an id and userName for accessibility
     *
     * @example
     * ```tsx
     * const users = [
     *   {
     *     id: "1",
     *     userName: "John Doe",
     *     src: "/john.jpg",
     *     info: { role: "Developer", email: "john@company.com" }
     *   },
     *   {
     *     id: "2",
     *     userName: "Jane Smith",
     *     color: "green"
     *   }
     * ];
     * ```
     */
    users: AvatarGroupUser[];
    /**
     * Size variant for all avatars in the group
     *
     * Controls the diameter and overlap spacing:
     * - `xsmall`: 24px avatars with -4px overlap - for compact lists
     * - `small`: 36px avatars with -8px overlap - for table rows
     * - `medium`: 48px avatars with -12px overlap - standard size
     * - `large`: 64px avatars with -16px overlap - for prominent displays
     *
     * @default "medium"
     * @example
     * ```tsx
     * // Compact display
     * <AvatarGroup users={users} size="xsmall" />
     *
     * // Standard display
     * <AvatarGroup users={users} size="medium" />
     *
     * // Prominent display
     * <AvatarGroup users={users} size="large" />
     * ```
     */
    size?: 'xsmall' | 'small' | 'medium' | 'large';
    /**
     * Maximum number of avatars to display before showing "More" indicator
     *
     * Accepts any positive number. When users exceed maxVisible, remaining count shows as "+N" indicator.
     * - The more indicator takes the place of the last visible avatar slot
     * - Minimum value of 1 allows showing just the "+N" indicator
     * - Higher values accommodate different layout requirements
     *
     * @default 5
     * @example
     * ```tsx
     * // Show only more indicator for compact display
     * <AvatarGroup users={users} maxVisible={1} />
     *
     * // Show max 3 avatars, rest in "+N" indicator
     * <AvatarGroup users={users} maxVisible={3} />
     *
     * // Show many avatars for wide layouts
     * <AvatarGroup users={users} maxVisible={10} />
     * ```
     */
    maxVisible?: number;
    /**
     * Text displayed in the more indicator tooltip on hover/focus
     * Provides context about what happens when clicked
     * Only relevant when users array exceeds maxVisible count
     *
     * @default "Click to view all collaborators"
     * @example
     * ```tsx
     * // For sharing use case
     * <AvatarGroup
     *   users={users}
     *   moreIndicatorTooltip="Click to view all shared users"
     * />
     *
     * // For team members
     * <AvatarGroup
     *   users={users}
     *   moreIndicatorTooltip="View all team members"
     * />
     * ```
     */
    moreIndicatorTooltip?: string;
    /**
     * Callback fired when the more indicator is clicked
     * Should open modal, navigate to user list, or show expanded view
     * Only relevant when users array exceeds maxVisible count
     *
     * @param hiddenUsers - Array of users not currently visible
     * @param totalCount - Total number of users in the group
     *
     * @example
     * ```tsx
     * <AvatarGroup
     *   users={allUsers}
     *   onMoreIndicatorClick={(hiddenUsers, totalCount) => {
     *     // Open sharing modal with full user list
     *     openSharingModal({ users: allUsers, count: totalCount });
     *
     *     // Access hidden count: hiddenUsers.length
     *     console.log(`${hiddenUsers.length} more users available`);
     *   }}
     * />
     * ```
     */
    onMoreIndicatorClick?: (hiddenUsers: AvatarGroupUser[], totalCount: number) => void;
    /**
     * Whether individual avatars should be focusable and interactive
     *
     * When true:
     * - Each avatar becomes keyboard focusable
     * - Avatars show user popover on hover/focus (if user.info provided)
     * - Avatars support click handlers
     *
     * @default false
     * @example
     * ```tsx
     * // Interactive avatars with user popovers
     * <AvatarGroup
     *   users={usersWithInfo}
     *   interactive
     *   onUserClick={(user) => openProfile(user.id)}
     * />
     * ```
     */
    interactive?: boolean;
    /**
     * Callback fired when an individual avatar is clicked
     * Only relevant when interactive=true
     *
     * @param user - The clicked user data
     * @param index - Position of user in the visible avatars (0-based)
     *
     * @example
     * ```tsx
     * <AvatarGroup
     *   users={users}
     *   interactive
     *   onUserClick={(user, index) => {
     *     console.log(`Clicked ${user.userName} at position ${index}`);
     *     navigateToProfile(user.id);
     *   }}
     * />
     * ```
     */
    onUserClick?: (user: AvatarGroupUser, index: number) => void;
    /**
     * ARIA label for the entire avatar group
     * Provides context for screen readers about what the group represents
     *
     * @default "Avatar group"
     * @example
     * ```tsx
     * // For sharing context
     * <AvatarGroup
     *   users={users}
     *   aria-label="Users with access to this document"
     * />
     *
     * // For team context
     * <AvatarGroup
     *   users={users}
     *   aria-label="Project team members"
     * />
     * ```
     */
    'aria-label'?: string;
    /**
     * Additional CSS classes to apply to the avatar group container
     * @example
     * ```tsx
     * <AvatarGroup users={users} className="custom-group-spacing" />
     * ```
     */
    className?: string;
    /**
     * Test identifier for automated testing
     * @example
     * ```tsx
     * <AvatarGroup users={users} data-testid="collaborator-avatars" />
     * ```
     */
    'data-testid'?: string;
    /**
     * Whether the avatar group is disabled
     * When disabled:
     * - Avatars use 'disabled' state for proper Avatar styling
     * - More indicator becomes non-interactive with disabled styling
     * - All click handlers are prevented
     *
     * @default false
     * @example
     * ```tsx
     * // Disabled group for read-only contexts
     * <AvatarGroup
     *   users={collaborators}
     *   disabled={true}
     *   aria-label="Inactive project collaborators"
     * />
     * ```
     */
    disabled?: boolean;
}
/**
 * Avatar Group size variant union
 * @see {@link AvatarGroupProps.size} for detailed usage examples
 */
export type AvatarGroupSize = AvatarGroupProps['size'];
/**
 * Avatar Group max visible count - any positive number
 * @see {@link AvatarGroupProps.maxVisible} for detailed usage examples
 */
export type AvatarGroupMaxVisible = number;
